import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeTabBar, PrimeTextFormField;
import 'dart:async';import 'dart:convert';import 'dart:io';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/component_catalogue.dart';
final labels=CatalogueLabels.fromMetadata(jsonDecode(File('../primecare_ui/catalogs/component-catalogue.registration.json').readAsStringSync()),'en');
Finder cy(String key)=>find.byWidgetPredicate((w)=>w is Semantics&&w.properties.identifier=='component-catalogue-$key');
Widget scene(Widget child,{bool rtl=false})=>MaterialApp(home:Scaffold(body:Directionality(textDirection:rtl?TextDirection.rtl:TextDirection.ltr,child:SingleChildScrollView(child:child))));
void main(){
 testWidgets('actions preserve accessible labels busy guard and typed input on rejection',(t)async{final pending=Completer<void>(),input=TextEditingController(text:'keep'),kit=PrimeComponentKit(labels,'account');var calls=0;await t.pumpWidget(scene(Column(children:[kit.field('input',input),kit.button('button',()async{calls++;await pending.future;})])));await t.tap(cy('button'));await t.pump();await t.tap(cy('button'),warnIfMissed:false);expect(calls,1);expect(find.text(labels.text('button')),findsOneWidget);pending.completeError(StateError('denied'));await t.pumpAndSettle();expect(find.text(labels.text('actionError')),findsOneWidget);expect(input.text,'keep');await t.pumpWidget(const SizedBox.shrink());input.dispose();});
 for(final rejects in [false,true])testWidgets('resource suffix change isolates old ${rejects?'failure':'success'} from a pending new action',(t)async{
  final suffix=ValueNotifier('-first'),first=Completer<void>(),next=Completer<void>();var firstCalls=0,nextCalls=0;
  await t.pumpWidget(scene(ValueListenableBuilder<String>(valueListenable:suffix,builder:(context,value,child)=>PrimeCatalogueAction(labels:labels,scope:'account',control:'button',suffix:value,action:()async{if(value=='-first'){firstCalls++;await first.future;}else{nextCalls++;await next.future;}}))));
  await t.tap(cy('button-first'));await t.pump();expect(firstCalls,1);
  suffix.value='-second';await t.pumpAndSettle();
  final button=find.descendant(of:cy('button-second'),matching:find.byType(TextButton));
  expect(t.widget<TextButton>(button).onPressed,isNotNull);expect(find.text(labels.text('loading')),findsNothing);
  await t.tap(button);await t.pump();expect(nextCalls,1);expect(t.widget<TextButton>(button).onPressed,isNull);
  if(rejects){first.completeError(StateError('old resource denied'));}else{first.complete();}await t.pumpAndSettle();
  expect(t.widget<TextButton>(button).onPressed,isNull);expect(find.text(labels.text('actionError')),findsNothing);expect(find.text(labels.text('success')),findsNothing);expect(nextCalls,1);expect(firstCalls,1);
  next.complete();await t.pumpAndSettle();expect(find.text(labels.text('success')),findsOneWidget);expect(t.widget<TextButton>(button).onPressed,isNotNull);expect(t.takeException(),isNull);
  await t.pumpWidget(const SizedBox.shrink());suffix.dispose();
 });
 for(final rejects in [false,true])testWidgets('resource suffix change clears completed ${rejects?'error':'success'} feedback',(t)async{
  final suffix=ValueNotifier('-first');var calls=0;
  await t.pumpWidget(scene(ValueListenableBuilder<String>(valueListenable:suffix,builder:(context,value,child)=>PrimeCatalogueAction(labels:labels,scope:'account',control:'button',suffix:value,action:()async{calls++;if(rejects)throw StateError('denied');}))));
  await t.tap(cy('button-first'));await t.pumpAndSettle();expect(find.text(labels.text(rejects?'actionError':'success')),findsOneWidget);
  suffix.value='-second';await t.pumpAndSettle();expect(find.text(labels.text('actionError')),findsNothing);expect(find.text(labels.text('success')),findsNothing);expect(calls,1);
  expect(t.widget<TextButton>(find.descendant(of:cy('button-second'),matching:find.byType(TextButton))).onPressed,isNotNull);expect(t.takeException(),isNull);
  await t.pumpWidget(const SizedBox.shrink());suffix.dispose();
 });
 testWidgets('form validation and rejected acknowledgement never erase user input',(t)async{final kit=PrimeComponentKit(labels,'account'),key=GlobalKey<FormState>(),input=TextEditingController();var calls=0,fail=true;await t.pumpWidget(scene(kit.form(key,[kit.field('input',input,required:true)],()async{calls++;if(fail)throw StateError('denied');},minColumnWidth:240,gap:16),rtl:true));await t.tap(cy('confirm-form'));await t.pumpAndSettle();expect(calls,0);expect(find.text(labels.text('required')),findsOneWidget);await t.enterText(find.byType(PrimeTextFormField),'typed');await t.tap(cy('confirm-form'));await t.pumpAndSettle();expect(calls,1);expect(input.text,'typed');fail=false;await t.tap(cy('confirm-form'));await t.pumpAndSettle();expect(calls,2);expect(t.takeException(),isNull);await t.pumpWidget(const SizedBox.shrink());input.dispose();});
 testWidgets('registered radio switch checkbox and selection use controlled state',(t)async{final kit=PrimeComponentKit(labels,'account');var checked=false,switched=false;String? value='a',radio='a';await t.pumpWidget(scene(StatefulBuilder(builder:(context,set)=>Column(children:[kit.select({'a':'A','b':'B'},value,(v)=>set(()=>value=v)),kit.boolean('checkbox',checked,(v)=>set(()=>checked=v)),kit.boolean('switch',switched,(v)=>set(()=>switched=v)),kit.radio({'a':'A','b':'B'},radio,(v)=>set(()=>radio=v))]))));await t.tap(cy('checkbox'));await t.pumpAndSettle();await t.tap(cy('switch'));await t.pumpAndSettle();await t.tap(cy('radio-1'));await t.pumpAndSettle();expect([checked,switched,radio],[true,true,'b']);await t.tap(cy('select'));await t.pumpAndSettle();await t.tap(find.text('B').last);await t.pumpAndSettle();expect(value,'b');expect(t.takeException(),isNull);});
 testWidgets('menus tabs accordion and tooltip expose keyboard and disabled states',(t)async{final kit=PrimeComponentKit(labels,'account');String? selected;await t.pumpWidget(scene(Column(children:[kit.menu({'a':'A','b':'B'},(v)=>selected=v,disabled:{'b'}),kit.tabs(['tabOne','tabTwo'],[const Text('one'),const Text('two')],180),kit.accordion(const Text('details')),kit.tooltip('safe help')]),rtl:true));await t.tap(cy('menu'));await t.pumpAndSettle();expect(t.widget<PopupMenuItem<String>>(find.byWidgetPredicate((w)=>w is PopupMenuItem<String>&&w.value=='b')).enabled,false);await t.sendKeyEvent(LogicalKeyboardKey.escape);await t.pumpAndSettle();expect(selected,isNull);await t.tap(cy('tab-two'));await t.pumpAndSettle();expect(DefaultTabController.of(t.element(find.byType(PrimeTabBar))).index,1);await t.tap(cy('accordion'));await t.pumpAndSettle();expect(find.text('details'),findsOneWidget);final trigger=find.descendant(of:cy('tooltip-trigger'),matching:find.byType(Text));Focus.of(t.element(trigger)).requestFocus();await t.pumpAndSettle();expect(find.text('safe help'),findsOneWidget);await t.sendKeyEvent(LogicalKeyboardKey.escape);await t.pumpAndSettle();expect(find.text('safe help'),findsNothing);expect(t.takeException(),isNull);});
 testWidgets('confirmation closes only on acknowledgement and returns launcher focus',(t)async{var fail=true;await t.pumpWidget(scene(PrimeCatalogueModal(labels:labels,scope:'account',control:'dialog',child:const Text('question'),approve:()async{if(fail)throw StateError('denied');})));await t.tap(cy('button-dialog'));await t.pumpAndSettle();await t.tap(cy('confirm-dialog'));await t.pumpAndSettle();expect(find.byType(Dialog),findsOneWidget);expect(find.text(labels.text('actionError')),findsOneWidget);fail=false;await t.tap(cy('confirm-dialog'));await t.pumpAndSettle();expect(find.byType(Dialog),findsNothing);expect(t.widget<TextButton>(find.descendant(of:cy('button-dialog'),matching:find.byType(TextButton))).focusNode!.hasFocus,true);});
 testWidgets('a late confirmation removes only its owned dialog under a newer route',(t)async{final pending=Completer<void>();await t.pumpWidget(scene(PrimeCatalogueModal(labels:labels,scope:'account',control:'dialog',child:const Text('original question'),approve:()=>pending.future)));await t.tap(cy('button-dialog'));await t.pumpAndSettle();await t.tap(cy('confirm-dialog'));await t.pump();final context=t.element(find.byType(Dialog)),nav=Navigator.of(context);unawaited(nav.push(DialogRoute<void>(context:context,builder:(_)=>const AlertDialog(content:Text('newer route')))));await t.pumpAndSettle();pending.complete();await t.pumpAndSettle();expect(find.text('newer route'),findsOneWidget);expect(find.text('original question'),findsNothing);nav.pop();await t.pumpAndSettle();expect(t.takeException(),isNull);});
 for(final first in ['dialog','drawer'])testWidgets('changing $first control retires only its owned pending modal',(t)async{
  final next=first=='dialog'?'drawer':'dialog',control=ValueNotifier(first),pending=Completer<void>();var approvals=0;
  await t.pumpWidget(scene(ValueListenableBuilder<String>(valueListenable:control,builder:(context,value,child)=>PrimeCatalogueModal(labels:labels,scope:'account',control:value,child:Text('owned $value question'),approve:()async{approvals++;if(value==first)await pending.future;}))));
  final oldLauncher=first=='dialog'?'button-dialog':'menu-drawer',newLauncher=next=='dialog'?'button-dialog':'menu-drawer';
  await t.tap(cy(oldLauncher));await t.pumpAndSettle();await t.tap(cy('confirm-$first'));await t.pump();expect(approvals,1);
  final context=t.element(find.byType(Dialog)),nav=Navigator.of(context);
  unawaited(nav.push(DialogRoute<void>(context:context,builder:(_)=>const AlertDialog(content:Text('unrelated top route')))));await t.pumpAndSettle();
  expect(find.text('owned $first question',skipOffstage:false),findsOneWidget);control.value=next;await t.pumpAndSettle();expect(find.text('owned $first question',skipOffstage:false),findsNothing);expect(find.text('unrelated top route'),findsOneWidget);
  pending.complete();await t.pumpAndSettle();expect(find.text('unrelated top route'),findsOneWidget);expect(approvals,1);
  nav.pop();await t.pumpAndSettle();await t.tap(cy(newLauncher));await t.pumpAndSettle();expect(find.text('owned $next question'),findsOneWidget);
  await t.tap(cy('confirm-$next'));await t.pumpAndSettle();expect(find.byType(Dialog),findsNothing);expect(approvals,2);expect(t.takeException(),isNull);
  await t.pumpWidget(const SizedBox.shrink());control.dispose();
 });
 testWidgets('literal code and clipboard rejection keep the source intact',(t)async{const source='<script>alert("x")</script> const ready = true;';String? copied;var fail=true;await t.pumpWidget(scene(PrimeCodePreview(labels:labels,scope:'account',code:source,copy:(v)async{if(fail)throw StateError('denied');copied=v;})));expect(t.widget<SelectableText>(find.byType(SelectableText)).textSpan!.toPlainText(),source);await t.tap(cy('copy'));await t.pumpAndSettle();expect(find.text(labels.text('copyError')),findsOneWidget);fail=false;await t.tap(cy('copy'));await t.pumpAndSettle();expect(copied,source);});
 testWidgets('async scope replacement ignores old data and displays actual errors',(t)async{final old=Completer<String>();await t.pumpWidget(scene(PrimeAsyncBoundary<String>(scope:'old',future:old.future,labels:labels,builder:Text.new)));await t.pump();expect(find.text(labels.text('loading')),findsOneWidget);await t.pumpWidget(scene(PrimeAsyncBoundary<String>(scope:'new',future:Future.value('new data'),labels:labels,builder:Text.new)));await t.pumpAndSettle();old.complete('old data');await t.pumpAndSettle();expect(find.text('new data'),findsOneWidget);expect(find.text('old data'),findsNothing);final bad=Completer<String>();await t.pumpWidget(scene(PrimeAsyncBoundary<String>(scope:'new',future:bad.future,labels:labels,builder:Text.new)));bad.completeError(StateError('denied'));await t.pumpAndSettle();expect(find.text(labels.text('error')),findsOneWidget);});
 testWidgets('countdown uses absolute time fires once and releases its timer',(t)async{var now=0,finished=0;await t.pumpWidget(scene(PrimeCountdown(labels:labels,scope:'account',deadline:10000,now:()=>now,onFinish:()=>finished++)));await t.pump();now=15000;await t.pump(const Duration(seconds:1));expect(finished,1);expect(find.text(labels.text('finished')),findsOneWidget);await t.pump(const Duration(seconds:5));expect(finished,1);await t.pumpWidget(const SizedBox.shrink());await t.pump(const Duration(seconds:5));expect(finished,1);});
}
